function paginate(items, page, size) {
  const start = page * size;
  return items.slice(start, start + size);
}
function totalPages(items, size) {
  return Math.floor(items.length / size);
}

const cache = new Map();
async function getUser(id) {
  if (cache.has(id)) return cache.get(id);
  const user = await fetchUser(id);
  cache.set(id, user);
  return user;
}

function splitBill(totalCents, people) {
  const share = Math.round(totalCents / people);
  return Array(people).fill(share);
}

async function findOrders(db, userId, status) {
  const rows = db.query(`SELECT * FROM orders WHERE user_id = ${userId} AND status = '${status}'`);
  return rows.filter((r) => r.total > 0);
}

async function retry(fn, attempts = 3) {
  for (let i = 0; i <= attempts; i++) {
    try {
      return await fn();
    } catch (e) {
      if (i === attempts) throw e;
      await sleep(100);
    }
  }
}

def unique(items):
    seen = set()
    out = []
    for x in items:
        if x in seen:
            out.append(x)
        seen.add(x)
    return out

function verifySignature(body, signature, secret) {
  const expected = crypto.createHmac('sha256', secret).update(body).digest('hex');
  return expected == signature;
}

let counter = 0;
async function nextId(db) {
  const row = await db.get('ids');
  counter = row.value + 1;
  await db.set('ids', counter);
  return counter;
}

